<script lang="ts">
 import {onMount} from 'svelte'; import {Chart,RadarController,RadialLinearScale,PointElement,LineElement,Filler,Tooltip} from 'chart.js'; import type {CategoryWeight,RealParkFeature} from '../types/municipality'; import {valueFor} from '../lib/realMunicipality'; Chart.register(RadarController,RadialLinearScale,PointElement,LineElement,Filler,Tooltip);
 let {park,weights}:{park:RealParkFeature;weights:CategoryWeight[]}=$props();let canvas:HTMLCanvasElement;let chart:Chart|undefined;const render=()=>{chart?.destroy();chart=new Chart(canvas,{type:'radar',data:{labels:weights.map(w=>w.label),datasets:[{data:weights.map(w=>valueFor(park,w.score_field)),backgroundColor:'rgba(53,122,85,.17)',borderColor:'#357a55',pointBackgroundColor:'#173e34',spanGaps:false,borderWidth:2}]},options:{responsive:true,maintainAspectRatio:false,layout:{padding:14},plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.raw===null?'Unavailable':`${Number(c.raw).toFixed(1)} / 100`}}},scales:{r:{min:0,max:100,ticks:{display:false,stepSize:25},grid:{color:'#d9e1dc'},angleLines:{color:'#d9e1dc'},pointLabels:{color:'#354d42',font:{size:10,weight:600}}}}}})};onMount(()=>{render();return()=>chart?.destroy()});$effect(()=>{park;weights;if(canvas)render()});
</script><div class="persona-chart"><canvas bind:this={canvas} aria-label="Six-category persona score radar chart"></canvas></div>
